function deleteNode(node, key) {
  if (node === null) return null;                         // key isn't in the tree
  if (key < node.val) node.left = deleteNode(node.left, key);
  else if (key > node.val) node.right = deleteNode(node.right, key);
  else {
    if (node.left === null) return node.right;            // no left child: the right takes its place
    if (node.right === null) return node.left;            // no right child: the left takes its place
    let next = node.right;                                // two children: the successor is the
    while (next.left !== null) next = next.left;          // smallest value in the right subtree
    node.val = next.val;                                  // copy it here...
    node.right = deleteNode(node.right, next.val);        // ...and delete it from the right
  }
  return node;
}

def delete_node(node, key):
    if node is None:
        return None                       # key isn't in the tree
    if key < node.val:
        node.left = delete_node(node.left, key)
    elif key > node.val:
        node.right = delete_node(node.right, key)
    else:
        if node.left is None:
            return node.right             # no left child: the right takes its place
        if node.right is None:
            return node.left              # no right child: the left takes its place
        nxt = node.right                  # two children: the successor is the
        while nxt.left is not None:       # smallest value in the right subtree
            nxt = nxt.left
        node.val = nxt.val                # copy it here...
        node.right = delete_node(node.right, nxt.val)   # ...and delete it from the right
    return node

TreeNode deleteNode(TreeNode node, int key) {
    if (node == null) return null;                        // key isn't in the tree
    if (key < node.val) node.left = deleteNode(node.left, key);
    else if (key > node.val) node.right = deleteNode(node.right, key);
    else {
        if (node.left == null) return node.right;         // no left child: the right takes its place
        if (node.right == null) return node.left;         // no right child: the left takes its place
        TreeNode next = node.right;                       // two children: the successor is the
        while (next.left != null) next = next.left;       // smallest value in the right subtree
        node.val = next.val;                              // copy it here...
        node.right = deleteNode(node.right, next.val);    // ...and delete it from the right
    }
    return node;
}

TreeNode* deleteNode(TreeNode* node, int key) {
    if (node == nullptr) return nullptr;                  // key isn't in the tree
    if (key < node->val) node->left = deleteNode(node->left, key);
    else if (key > node->val) node->right = deleteNode(node->right, key);
    else {
        if (node->left == nullptr) return node->right;    // no left child: the right takes its place
        if (node->right == nullptr) return node->left;    // no right child: the left takes its place
        TreeNode* next = node->right;                     // two children: the successor is the
        while (next->left != nullptr) next = next->left;  // smallest value in the right subtree
        node->val = next->val;                            // copy it here...
        node->right = deleteNode(node->right, next->val); // ...and delete it from the right
    }
